CREATE TABLE `catalogues` (`id` BIGINT NOT NULL AUTO_INCREMENT , `title` TEXT NULL , `description` TEXT NULL DEFAULT NULL , `created` BIGINT NULL DEFAULT NULL , `edited` BIGINT NULL DEFAULT NULL , `owner` BIGINT UNSIGNED NOT NULL , `owner_visible` TINYINT(1) UNSIGNED NOT NULL DEFAULT '0' , `private` TINYINT(1) UNSIGNED NOT NULL DEFAULT '1' , `visible_to` TEXT NULL DEFAULT NULL , `is_admin` TINYINT(1) UNSIGNED NOT NULL DEFAULT '0' , `deleted` TINYINT(1) UNSIGNED NOT NULL DEFAULT '0' , PRIMARY KEY (`id`)) ENGINE = InnoDB;
CREATE TABLE `catalogues_relations` (`id` BIGINT NOT NULL AUTO_INCREMENT , `ord` BIGINT UNSIGNED NOT NULL , `model` BIGINT NOT NULL , `catalogue` BIGINT UNSIGNED NOT NULL , `item` BIGINT UNSIGNED NOT NULL , PRIMARY KEY (`id`)) ENGINE = InnoDB;
CREATE TABLE `catalogues_imports` (`id` BIGINT NOT NULL AUTO_INCREMENT , `catalogue` INT NOT NULL , `owner` INT NOT NULL , `ord` BIGINT NULL , PRIMARY KEY (`id`)) ENGINE = InnoDB;
ALTER TABLE `catalogues` ADD `feed` TINYINT(1) UNSIGNED NOT NULL DEFAULT '0' AFTER `is_admin`;
